                        + "term_version, segment_count, language_count, approval_count, evidence_json, status, "
                        + "revoked_at, revoked_by, revoke_reason, created_at FROM archive_package "
                        + "WHERE document_id = ? ORDER BY archive_version",
                PACKAGE_MAPPER, documentId);
    }

    /** 对归档包行加写锁后读取，串行化撤销。 */
    public Optional<ArchivePackageRow> findArchivePackageForUpdate(long documentId, int archiveVersion) {
        List<ArchivePackageRow> rows = jdbc.query(
                "SELECT archive_id, document_id, archive_version, published_version, target_languages, "
