        jdbc.update("UPDATE archive_package SET status = 'REVOKED', revoked_at = ?, revoked_by = ?, "
                        + "revoke_reason = ? WHERE archive_id = ?",
                Timestamp.from(at), actor, reason, archiveId);
    }

    /** 查询归档包逐段证据，按段落、语种稳定排序。 */
