    public ResponseEntity<String> batchArchive(@PathVariable long documentId,
                                               @RequestHeader("X-Actor-Id") String actorId,
                                               @Valid @RequestBody BatchArchiveRequest request) {
        String operation = "POST /api/documents/" + documentId + "/archives/batch";
        return writeExecutor.execute(request.requestId(), hash(operation, actorId, canonicalBatch(request)),
                () -> WriteResult.of(201, archiveService.batchCreateArchives(documentId, actorId, request)))
                .toResponseEntity();
    }

    /** 撤回发布：撤回后不能新建归档包，历史证据保留。 */
    @PostMapping("/releases/{publishedVersion}/withdraw")
    public ResponseEntity<String> withdrawRelease(@PathVariable long documentId,
                                                  @PathVariable int publishedVersion,
                                                  @RequestHeader("X-Actor-Id") String actorId,
                                                  @Valid @RequestBody WithdrawReleaseRequest request) {
        String operation = "POST /api/documents/" + documentId + "/releases/" + publishedVersion + "/withdraw";
        return writeExecutor.execute(request.requestId(), hash(operation, actorId, publishedVersion, request.reason()),
                () -> WriteResult.of(200,
                        archiveService.withdrawRelease(documentId, publishedVersion, actorId, request)))
                .toResponseEntity();
    }

    /** 撤销归档：仅标记访问失效并保留原因，证据不改写。 */
    @PostMapping("/archives/{archiveVersion}/revoke")
    public ResponseEntity<String> revokeArchive(@PathVariable long documentId,
                                                @PathVariable int archiveVersion,
                                                @RequestHeader("X-Actor-Id") String actorId,
                                                @Valid @RequestBody RevokeArchiveRequest request) {
        String operation = "POST /api/documents/" + documentId + "/archives/" + archiveVersion + "/revoke";
        return writeExecutor.execute(request.requestId(), hash(operation, actorId, archiveVersion, request.reason()),
                () -> WriteResult.of(200,
                        archiveService.revokeArchive(documentId, archiveVersion, actorId, request)))
                .toResponseEntity();
    }

    /** 查询归档包明细；已撤销返回 410，撤回发布后的历史包仍受限可查（走历史/诊断）。 */
    @GetMapping("/archives/{archiveVersion}")
    public ResponseEntity<ArchiveDtos.ArchiveDetailView> getArchive(@PathVariable long documentId,
                                                                    @PathVariable int archiveVersion) {
        return ResponseEntity.ok(archiveService.getArchive(documentId, archiveVersion));
    }

    /** 查询归档领域事件历史，按提交顺序稳定排序。 */
    @GetMapping("/archive-history")
    public ResponseEntity<ArchiveDtos.ArchiveHistoryResponse> getHistory(@PathVariable long documentId) {
        return ResponseEntity.ok(archiveService.getHistory(documentId));
    }

    /** 诊断查询：可按发布版本与 UTC 左闭右开时间区间过滤，返回实际值/要求值/差额。 */
    @GetMapping("/archive-diagnostics")
    public ResponseEntity<ArchiveDtos.ArchiveDiagnosticResponse> diagnose(
            @PathVariable long documentId,
            @RequestParam(name = "publishedVersion", required = false) Integer publishedVersion,
            @RequestParam(name = "from", required = false) Instant from,
            @RequestParam(name = "to", required = false) Instant to) {
        return ResponseEntity.ok(archiveService.diagnose(documentId, publishedVersion, from, to));
    }

    /** 单包指纹中的规范化对象集合：语种集合归一为小写字典序，空集合语义为“全部语种”。 */
    private Map<String, Object> canonicalSingle(int publishedVersion, List<String> languages) {
        Map<String, Object> canonical = new LinkedHashMap<>();
        canonical.put("publishedVersion", publishedVersion);
        canonical.put("targetLanguages", normalizeLanguageSet(languages));
        return canonical;
    }

    /** 批量指纹：项按发布版本排序，语种集合规范化，保证集合语义不依赖请求顺序或分隔符拼接。 */
    private List<Map<String, Object>> canonicalBatch(BatchArchiveRequest request) {
        return request.items().stream()
                .map(item -> canonicalSingle(item.publishedVersion(), item.targetLanguages()))
                .sorted((a, b) -> Integer.compare((int) a.get("publishedVersion"), (int) b.get("publishedVersion")))
                .toList();
    }

    private List<String> normalizeLanguageSet(List<String> languages) {
        return languages.stream()
                .map(language -> language.trim().toLowerCase(Locale.ROOT))
                .distinct()
                .sorted()
                .toList();
    }

    /** 幂等指纹：操作类型 + 操作者 + 规范化对象集合与全部影响结果字段的 SHA-256。 */
    private String hash(String operation, Object... parts) {
        try {
            StringBuilder canonical = new StringBuilder(operation);
            for (Object part : parts) {
                canonical.append('\n').append(objectMapper.writeValueAsString(part));
            }
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        } catch (Exception e) {
            throw new IllegalArgumentException("请求序列化失败", e);
        }
    }
}

