package com.example.starter.translation.archive;

import com.example.starter.translation.archive.ArchiveDtos.BatchArchiveRequest;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * 归档写操作幂等指纹工具。
 *
 * <p>指纹覆盖操作类型（含路径变量）、操作者、规范化对象集合与全部影响结果的字段。
 * 语种集合先 trim、小写、去重并字典序排序，再以 JSON 数组参与摘要——不使用任何分隔符拼接字符串，
 * 因此含逗号等字符的语种值不会造成不同集合指纹碰撞。</p>
 */
final class ArchiveFingerprint {

    private ArchiveFingerprint() {
    }

    /** 规范化语种集合：trim、小写、去重、字典序。 */
    static List<String> normalizeLanguageSet(List<String> languages) {
        return languages.stream()
                .map(language -> language.trim().toLowerCase(Locale.ROOT))
                .distinct()
                .sorted()
                .toList();
    }

    /** 单包指纹的规范化对象集合：发布版本 + 语种集合（空集合语义为“全部语种”，原样保留空）。 */
    static Map<String, Object> single(int publishedVersion, List<String> languages) {
        Map<String, Object> canonical = new LinkedHashMap<>();
        canonical.put("publishedVersion", publishedVersion);
        canonical.put("targetLanguages", normalizeLanguageSet(languages));
        return canonical;
    }

    /** 批量指纹：项按发布版本排序，集合规范化，顺序不同的等价请求得到相同结构。 */
    static List<Map<String, Object>> batch(BatchArchiveRequest request) {
        return request.items().stream()
                .map(item -> single(item.publishedVersion(), item.targetLanguages()))
                .sorted((a, b) -> Integer.compare((int) a.get("publishedVersion"), (int) b.get("publishedVersion")))
                .toList();
    }

    /** 计算 SHA-256 指纹：操作类型后逐段拼接操作者与规范化字段，以换行分隔。 */
    static String sha256(String operation, List<Object> parts) {
        try {
            StringBuilder canonical = new StringBuilder(operation);
            for (Object part : parts) {
                canonical.append('\n').append(part instanceof String s ? s : toJson(part));
            }
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }

    private static String toJson(Object value) {
        try {
            return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(value);
        } catch (Exception e) {
            throw new IllegalArgumentException("指纹序列化失败", e);
        }
    }
}

