    Set<String> dedupe = new LinkedHashSet<>();
    List<BatchItemInput> inputs = new ArrayList<>();
    for (var item : request.items()) {
        List<String> languages = normalizeRequestedLanguages(item.targetLanguages());
        if (!dedupe.add(item.publishedVersion() + "|" + String.join(",", languages))) {
            throw ApiException.unprocessable(
                    "批量归档存在重复项: 发布版本 " + item.publishedVersion() + " 语种集合 " + languages);
        }
        inputs.add(new BatchItemInput(item.publishedVersion(), languages));
